import{_ as o,c as e,o as a,a2 as d}from"./chunks/framework.CHomSxuB.js";const p=JSON.parse('{"title":"A股量化验证","description":"","frontmatter":{},"headers":[],"relativePath":"A股量化验证/index.md","filePath":"A股量化验证/index.md"}'),r={name:"A股量化验证/index.md"};function l(n,t,s,i,h,u){return a(),e("div",null,t[0]||(t[0]=[d(`<h1 id="a股量化验证" tabindex="-1">A股量化验证 <a class="header-anchor" href="#a股量化验证" aria-label="Permalink to &quot;A股量化验证&quot;">​</a></h1><blockquote><p>一句话：<strong>一个不预测、不荐股的短线验证体系</strong>——拿 2 万元本金级别的小账户视角，把&quot;盘面传言&quot;逐个丢进预注册统计机器里证真或证伪。 这里记录的不是&quot;明天买什么&quot;，而是&quot;哪些路走不通、哪条路还活着&quot;。</p></blockquote><hr><h2 id="这个系列在做什么" tabindex="-1">这个系列在做什么 <a class="header-anchor" href="#这个系列在做什么" aria-label="Permalink to &quot;这个系列在做什么&quot;">​</a></h2><p>市场里 90% 的&quot;短线秘诀&quot;都长这样：<strong>先有一个赚钱的故事情节，再找数据硬凑证据</strong>。 本系列反着来：先冻结协议 → 再写代码 → 只跑一次不调参 → 如实落盘，允许并预期 <code>NO_EDGE</code>。</p><p>目前所有验证线围绕同一个宇宙展开：<strong>主板（60/00 开头）涨停板接力/首板生态</strong>， 摩擦成本一律扣双边 0.35%，超额收益对标中证 1000（000852）。</p><hr><h2 id="战线全景-截至-2026-09-02" tabindex="-1">战线全景（截至 2026-09-02） <a class="header-anchor" href="#战线全景-截至-2026-09-02" aria-label="Permalink to &quot;战线全景（截至 2026-09-02）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>验证线</th><th>核心问题</th><th>裁决</th><th>状态</th></tr></thead><tbody><tr><td>Step 1 → 4</td><td>首板先锋（全市场最早封板）</td><td>秒级速度差能否转化为可交易超额</td><td><strong>有 edge（回测）</strong></td><td>🔴 <strong>前向追踪中</strong>（唯一活跃线）</td></tr><tr><td>Step 3</td><td>公告排雷（LLM 剔除高危利空）</td><td>剔除&quot;减持/利空&quot;龙头能否提升样本质量</td><td>排雷无正贡献（微损）</td><td>🔒 已证伪</td></tr><tr><td>Step 5 基线</td><td>连板接力（2进3 / 3进4 无差别）</td><td>连板晋级是否自带正期望</td><td><code>NO_EDGE</code>（近似抛硬币）</td><td>🔒 已证伪</td></tr><tr><td>V0.5 闸门</td><td>情绪温度计择时（昨日连板溢价）</td><td>退潮期能否被提前识别并规避</td><td><code>GATE_NO_EDGE</code></td><td>🔒 已证伪</td></tr><tr><td>V0.6</td><td>首板次日分歧低开低吸</td><td>&quot;黄金坑&quot;低吸是否优于无差别买入</td><td><code>NO_EDGE</code>（45.8% 胜率，接飞刀）</td><td>🔒 已证伪</td></tr><tr><td>V0.7 / D3</td><td>龙虎榜机构席位动量</td><td>交易所&quot;明牌&quot;资金净买是否有超额</td><td><code>NO_EDGE</code>（双家族，T+3 衰减坐实）</td><td>🔒 已证伪</td></tr></tbody></table><blockquote><p>🔴 观测中 = 尚未判决，正在用时间攒样本（Step 4 前向追踪，每天 15:15 自动结算） 🔒 已证伪 = 全量回测已完成终审裁决，结论封存；<strong>&quot;无持续产出&quot;是证伪线的正常状态，不是坏了</strong></p></blockquote><hr><h2 id="为什么值得信-四条统计纪律" tabindex="-1">为什么值得信：四条统计纪律 <a class="header-anchor" href="#为什么值得信-四条统计纪律" aria-label="Permalink to &quot;为什么值得信：四条统计纪律&quot;">​</a></h2><ol><li><strong>预注册（Pre-registration）</strong>：每个假设在跑数据前先写成协议（家族、阈值、裁决规则）， 冻结后不许改。改协议 = 新版本号 + 全量重算。协议文件本身就是要交付的&quot;卷宗&quot;。</li><li><strong>cluster bootstrap + BH-FDR</strong>：按&quot;事件/日期&quot;聚类重采样（不是按笔数）， 多重检验用 Benjamini-Hochberg 控 FDR，防&quot;10 个桶里挑 1 个显著的&quot;。</li><li><strong>n 红线</strong>：样本不足 30 不输出结论；报告永远双列 <code>n_events / n_pairs</code>。</li><li><strong>时间胶囊与未来函数防线</strong>：已归档事件标题/摘要不可改；行情只取 <code>available_time</code> （盘前→09:30、午间→13:00、盘后→次日 09:30）之后的，杜绝拿&quot;今天的信息&quot;算&quot;昨天的收益&quot;。</li></ol><h2 id="执行口径-重要-曾引发认知混乱-已审计钉死" tabindex="-1">执行口径（重要，曾引发认知混乱，已审计钉死） <a class="header-anchor" href="#执行口径-重要-曾引发认知混乱-已审计钉死" aria-label="Permalink to &quot;执行口径（重要，曾引发认知混乱，已审计钉死）&quot;">​</a></h2><p>Step 1/4 的收益计算是 <strong>A 股 T+1 制度下真实可执行的跨日持仓</strong>，不是&quot;当日买当日卖&quot;：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T 日盘中首板确认时以涨停价(Close_T)排单买入 → 隔夜持有 → T+1 收盘(Close_T+1)卖出</span></span>
<span class="line"><span>收益 Ret = Close_{T+1} / Close_T − 1 − 0.35%（双边摩擦）</span></span></code></pre></div><p><strong>unfilled_guard（打板成交性防线）</strong>：若 T+1 开盘 ≥ Close_T × 1.095（一字/近一字开盘）， 说明 T 日封板极强、散户通道根本排不进单 → 该样本标记 <code>UNFILLED</code> 不计入可成交样本。 这是&quot;打板没买到的代理变量&quot;，<strong>不是</strong>&quot;次日开盘买入&quot;假设。</p><blockquote><p>这条口径曾因代码注释与实现不符引发过一轮认知混乱，现已修复并通过历史账本逐笔审计 （见《数据洁净度审计》篇）。</p></blockquote><hr><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ul><li><a href="/A股量化验证/0-统计纪律与协议冻结.html">0. 统计纪律与协议冻结</a></li><li><a href="/A股量化验证/1-首板先锋.html">1. 首板先锋：唯一还活着的线（Step 1 回测 + Step 4 前向）</a></li><li><a href="/A股量化验证/2-公告排雷.html">2. 公告排雷：LLM 剔除利空龙头有用吗（Step 3）</a></li><li><a href="/A股量化验证/3-连板接力与情绪闸门.html">3. 连板接力与情绪闸门：抛硬币与择时幻觉（Step 5 / V0.5）</a></li><li><a href="/A股量化验证/4-分歧低吸.html">4. 分歧低吸：黄金坑还是接飞刀（V0.6）</a></li><li><a href="/A股量化验证/5-龙虎榜机构席位.html">5. 龙虎榜机构席位：明牌资金没有 alpha（D3 / V0.7）</a></li><li><a href="/A股量化验证/6-数据洁净度审计.html">6. 数据洁净度审计：注释与实现打架的一次复盘</a></li></ul>`,21)]))}const q=o(r,[["render",l]]);export{p as __pageData,q as default};
